// Library: YOU call the code, you keep control
import { formatDate } from 'date-fns';
console.log(formatDate(new Date(), 'dd/MM/yyyy'));

// Framework: IT calls your code (inversion of control)
// React decides WHEN to call your component
function MyComponent() {
  return <h1>Hello</h1>;
}
// -> React controls the lifecycle, not you

// Even a custom hook remains subject to React's rules
function useCounter() {
  return useState(0);
}

// React: JSX, logic and display in the same function
function Button({ label, onClick }) {
  return <button onClick={onClick}>{label}</button>;
}

// Vue: separate template, declarative syntax in the HTML
// <template><button @click="onClick">{{ label }}</button></template>

// Angular: class + decorator, TypeScript required
// @Component({ selector: 'app-button', template: '<button (click)="onClick()">{{label}}</button>' })
// class ButtonComponent { @Input() label; @Output() onClick = new EventEmitter(); }

// Angular adds two-way binding by default (ngModel)
// <input [(ngModel)]="label">

// Node.js: free file system access by default, modules via npm
const fs = require('fs');
fs.readFileSync('data.txt');

// Deno: security by default, explicit permissions required
// deno run --allow-read script.ts
Deno.readTextFileSync('data.txt');

// Bun: Node-compatible, but an all-in-one runtime and bundler, very fast to start
import { readFileSync } from 'fs';
readFileSync('data.txt');

// Bun and Deno also support top-level await natively
console.log(import.meta.url);

// Before bundling: several separate files
// utils.js
export function addition(a, b) { return a + b; }
// main.js
import { addition } from './utils.js';
console.log(addition(2, 3));

// After bundling (simplified): a single optimized file
